from pathlib import Path
import re

path = Path('apps/web-portal/components/policy-unified-form.tsx')
text = path.read_text(encoding='utf-8')

pattern = r'function LiveSummary\([\s\S]*?function SummaryRow'
replacement = '''function LiveSummary({completion,net,gst,gross,projectedOd,projectedTp,scheme,totalPayin,tds,payinAfterTds,retention,grossPayout}:{completion:number;net:number;gst:number;gross:number;projectedOd:number;projectedTp:number;scheme:number;totalPayin:number;tds:number;payinAfterTds:number;retention:number;grossPayout:number}){const anchorRef=useRef<HTMLDivElement>(null);const boundaryRef=useRef<HTMLElement>(null);const[position,setPosition]=useState<{left:number;width:number;top:number}|null>(null);useEffect(()=>{let frame=0;const boundaryElement=boundaryRef.current;if(!boundaryElement){setPosition(null);return;}const updatePosition=()=>{if(window.innerWidth<1280||!anchorRef.current){setPosition(null);return;}const anchorRect=anchorRef.current.getBoundingClientRect();const boundaryRect=boundaryElement.getBoundingClientRect();const fixedCard=document.getElementById("policy-summary-fixed-card");const cardHeight=fixedCard?.getBoundingClientRect().height??0;const preferredTop=Math.max(anchorRect.top,172);const boundaryTop=cardHeight>0?boundaryRect.bottom-cardHeight:preferredTop;setPosition({left:anchorRect.left,width:anchorRect.width,top:Math.min(preferredTop,boundaryTop)});};const scheduleUpdate=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(updatePosition);};updatePosition();frame=requestAnimationFrame(updatePosition);window.addEventListener("resize",scheduleUpdate);window.addEventListener("scroll",scheduleUpdate,true);const observer=new ResizeObserver(scheduleUpdate);observer.observe(boundaryElement);observer.observe(document.documentElement);return()=>{cancelAnimationFrame(frame);window.removeEventListener("resize",scheduleUpdate);window.removeEventListener("scroll",scheduleUpdate,true);observer.disconnect();};},[]);const complete=completion>=100;const card=<div className="overflow-hidden rounded-2xl border border-[#D9E2F0] bg-white shadow-[0_10px_30px_rgba(15,23,42,.10)]"><div className="flex items-center gap-3 border-b bg-[#F8FAFC] px-4 py-3"><div className="min-w-0 flex-1"><p className="text-[8px] font-bold uppercase tracking-[.11em] text-[#64748B]">Policy status</p><h3 className="mt-0.5 truncate text-[13px] font-semibold text-[#17365D]">Onboarding summary</h3></div><CompletionRing value={completion}/><span className={`shrink-0 rounded-full px-2.5 py-1 text-[8px] font-bold ${complete?"bg-[#E8F7EF] text-[#14845B]":"bg-[#FFF3CD] text-[#A96A00]"}`}>{complete?"Complete":"In progress"}</span></div><div className="p-4"><p className="mb-2 text-[8px] font-bold uppercase tracking-[.1em] text-[#64748B]">Financial summary</p><div className="divide-y divide-[#E8EDF3]"><SummaryRow label="Net premium" value={money.format(net)}/><SummaryRow label="GST" value={money.format(gst)}/><SummaryRow label="Gross premium" value={money.format(gross)} bold accent/><SummaryRow label="Projected OD pay-in" value={money.format(projectedOd)}/><SummaryRow label="Projected TP pay-in" value={money.format(projectedTp)}/><SummaryRow label="Insurer scheme" value={money.format(scheme)}/><SummaryRow label="Total pay-in" value={money.format(totalPayin)} bold/><SummaryRow label="TDS" value={money.format(tds)}/><SummaryRow label="Pay-in after TDS" value={money.format(payinAfterTds)} bold/><SummaryRow label="Retention" value={money.format(retention)} tone={retention<0?"negative":retention>0?"positive":"neutral"}/><SummaryRow label="Partner payout" value={money.format(grossPayout)} bold/></div></div></div>;return <aside ref={boundaryRef} className="xl:self-stretch"><div className="xl:hidden">{card}</div><div ref={anchorRef} className="hidden h-px w-full xl:block" aria-hidden="true"/>{position&&typeof document!=="undefined"?createPortal(<div id="policy-summary-fixed-card" className="fixed z-30" style={{left:position.left,width:position.width,top:position.top}}>{card}</div>,document.body):null}</aside>;}
function SummaryRow'''

new_text, count = re.subn(pattern, replacement, text, count=1)
if count != 1:
    raise SystemExit(f'LiveSummary replacement count={count}')
path.write_text(new_text, encoding='utf-8')
